// A bracket: a plate with four holes and rounded corners, and a post.
// Edit anything; it rebuilds as you type (Ctrl/Cmd+Enter to run now).
export const bracket = model("bracket", () => {
  const height = param("height", 10, { min: 4, max: 20, step: 1, unit: "mm", description: "Base plate thickness" });
  const postRadius = param("post_radius", 8, { min: 3, max: 15, unit: "mm" });

  const holes = [
    [-24, -14], [24, -14], [-24, 14], [24, 14],
  ].map(([x, y]) => cylinder(2.5, height, { align: ["center", "center", "min"] }).translate(x, y, 0));

  const plate = box(60, 40, height, { align: ["center", "center", "min"] })
    .fillet("|Z", 4)
    .cut(...holes)
    .label("base", { color: "#7f93ad", material: "aluminum" });

  const post = cylinder(postRadius, 30, { align: ["center", "center", "min"] })
    .translate(12, 0, height)
    .label("post", { color: "#c98b4a", material: "steel" });

  return assembly("bracket", [plate, post]);
});

await bracket();
